package mesh

import (
	"context"
	"encoding/json"
	"math"
	"os"
	"testing"
)

// The VTK baselines (testdata/upstream/vtk/mesh.json, generated by
// dicom-go-validation/scripts/vtk_fixtures.py with VTK 9.6.2 on synthetic
// phantoms; see THIRD_PARTY_PROVENANCE.json) are compared numerically; no
// VTK code or table is used.

type vtkMeshFixture struct {
	Phantoms []struct {
		Name     string `json:"name"`
		Dims     [3]int `json:"dims"`
		Radius   int    `json:"radius"`
		SemiAxes [3]int `json:"semi_axes"`
		Half     int    `json:"half"`
		Label    int    `json:"label"`
		Analytic *struct {
			Area   float64 `json:"area"`
			Volume float64 `json:"volume"`
		} `json:"analytic"`
		FlyingEdges *struct {
			Iso       float64 `json:"iso"`
			Triangles int     `json:"triangles"`
			Area      float64 `json:"area"`
			Volume    float64 `json:"volume"`
		} `json:"flying_edges"`
		SurfaceNets struct {
			Triangles int     `json:"triangles"`
			Area      float64 `json:"area"`
			Volume    float64 `json:"volume"`
		} `json:"surface_nets"`
	} `json:"phantoms"`
}

func loadVTKMeshFixture(t *testing.T) vtkMeshFixture {
	t.Helper()
	data, err := os.ReadFile("../testdata/upstream/vtk/mesh.json")
	if err != nil {
		t.Fatal(err)
	}
	var f vtkMeshFixture
	if err := json.Unmarshal(data, &f); err != nil {
		t.Fatal(err)
	}
	if len(f.Phantoms) < 6 {
		t.Fatalf("%d phantoms", len(f.Phantoms))
	}
	return f
}

// doubled is twice the offset of index i from the centre of n samples, as
// in vtk_fixtures.py.
func doubled(i, n int) float64 { return float64(2*i - (n - 1)) }

// TestMarchingCubesMatchesVTKFlyingEdges rebuilds the scalar fields of
// vtk_fixtures.py (sphere r² - |d|²/4 and ellipsoid 1 - Σ d²/4a², on a unit
// grid at the origin) and compares with vtkFlyingEdges3D at iso 0: the
// triangle count is identical (the same cells and cases produce the same
// loops; only the diagonal chosen for four- to six-sided loops may differ),
// area and volume agree within 0.1%, and both stay within 1% of the
// analytic solid.
func TestMarchingCubesMatchesVTKFlyingEdges(t *testing.T) {
	fixture := loadVTKMeshFixture(t)
	compared := 0
	for _, p := range fixture.Phantoms {
		if p.FlyingEdges == nil {
			continue
		}
		var value func(x, y, z int) float64
		switch p.Name {
		case "sphere":
			r := float64(p.Radius)
			value = func(x, y, z int) float64 {
				dx, dy, dz := doubled(x, p.Dims[0]), doubled(y, p.Dims[1]), doubled(z, p.Dims[2])
				return r*r - (dx*dx+dy*dy+dz*dz)/4
			}
		case "ellipsoid":
			a, b, c := float64(p.SemiAxes[0]), float64(p.SemiAxes[1]), float64(p.SemiAxes[2])
			value = func(x, y, z int) float64 {
				dx, dy, dz := doubled(x, p.Dims[0]), doubled(y, p.Dims[1]), doubled(z, p.Dims[2])
				return 1 - (dx*dx/(4*a*a) + dy*dy/(4*b*b) + dz*dz/(4*c*c))
			}
		default:
			t.Fatalf("unknown Flying Edges phantom %q", p.Name)
		}
		t.Run(p.Name, func(t *testing.T) {
			field := &FuncField{Size: p.Dims, Affine: identityAffine, Value: value}
			for _, open := range []bool{true, false} {
				m, err := Extract(context.Background(), field, Options{Iso: p.FlyingEdges.Iso, OpenBoundary: open})
				if err != nil {
					t.Fatal(err)
				}
				requireClosedManifold(t, m)
				area, volume := massProperties(m)
				want := p.FlyingEdges
				if len(m.Triangles) != want.Triangles || !relClose(area, want.Area, 1e-3) || !relClose(volume, want.Volume, 1e-3) {
					t.Fatalf("open %v: %d triangles, area %.6g, volume %.6g; vtkFlyingEdges3D %+v", open, len(m.Triangles), area, volume, *want)
				}
				if !relClose(volume, p.Analytic.Volume, 0.01) || (p.Analytic.Area > 0 && !relClose(area, p.Analytic.Area, 0.01)) {
					t.Fatalf("area %g, volume %g; analytic %+v", area, volume, *p.Analytic)
				}
			}
		})
		compared++
	}
	if compared != 2 {
		t.Fatalf("compared %d Flying Edges phantoms, want 2", compared)
	}
}

// inside mirrors the integer phantom tests of vtk_fixtures.py.
func vtkInside(name string, dims [3]int, radius int, semi [3]int, half, label, x, y, z int) bool {
	d := func(i, n int) int { return 2*i - (n - 1) }
	dx, dy, dz := d(x, dims[0]), d(y, dims[1]), d(z, dims[2])
	switch name {
	case "sphere":
		return dx*dx+dy*dy+dz*dz <= 4*radius*radius
	case "ellipsoid":
		a, b, c := 4*semi[0]*semi[0], 4*semi[1]*semi[1], 4*semi[2]*semi[2]
		return dx*dx*b*c+dy*dy*a*c+dz*dz*a*b <= a*b*c
	case "rotated-cube":
		h := 4 * half * half
		return (dx+dy)*(dx+dy) <= 2*h && (dx-dy)*(dx-dy) <= 2*h && dz*dz <= h
	}
	l := 0
	switch {
	case (x-12)*(x-12)+(y-20)*(y-20)+(z-20)*(z-20) <= 49:
		l = 1
	case x >= 24 && x <= 33 && y >= 10 && y <= 29 && z >= 12 && z <= 27:
		l = 2
	case (x-18)*(x-18)+(y-7)*(y-7)+(z-20)*(z-20) <= 16:
		l = 3
	}
	return l == label
}

// TestVoxelFacesMatchesVTKSurfaceNets: the voxel-exact surface of the
// binary phantoms equals vtkSurfaceNets3D without smoothing (the same
// quads): triangle count, area and volume agree, the volume is the voxel
// count, and the indexed mesh is closed and consistently oriented. Marching
// Cubes on the same masks at iso 0.5 is a closed manifold whose volume stays
// within 5% of the voxel count.
func TestVoxelFacesMatchesVTKSurfaceNets(t *testing.T) {
	fixture := loadVTKMeshFixture(t)
	for _, p := range fixture.Phantoms {
		t.Run(p.Name, func(t *testing.T) {
			data := make([]float32, p.Dims[0]*p.Dims[1]*p.Dims[2])
			count := 0
			for z := 0; z < p.Dims[2]; z++ {
				for y := 0; y < p.Dims[1]; y++ {
					for x := 0; x < p.Dims[0]; x++ {
						if vtkInside(p.Name, p.Dims, p.Radius, p.SemiAxes, p.Half, p.Label, x, y, z) {
							data[(z*p.Dims[1]+y)*p.Dims[0]+x] = 1
							count++
						}
					}
				}
			}
			field := &DenseField{Size: p.Dims, Affine: identityAffine, Data: data}
			m, err := Extract(context.Background(), field, Options{Method: VoxelFaces, Iso: 0.5})
			if err != nil {
				t.Fatal(err)
			}
			if err := m.Validate(); err != nil {
				t.Fatal(err)
			}
			if top := meshTopology(m); top.unpaired != 0 {
				t.Fatalf("voxel surface not closed: %+v", top)
			}
			area, volume := massProperties(m)
			want := p.SurfaceNets
			if len(m.Triangles) != want.Triangles || !relClose(area, want.Area, 1e-9) || !relClose(volume, want.Volume, 1e-9) {
				t.Fatalf("%d triangles, area %g, volume %g; vtkSurfaceNets3D %+v", len(m.Triangles), area, volume, want)
			}
			if !relClose(volume, float64(count), 1e-9) {
				t.Fatalf("volume %g, %d voxels", volume, count)
			}
			for i, n := range m.Normals {
				if l := math.Sqrt(float64(n[0]*n[0] + n[1]*n[1] + n[2]*n[2])); math.Abs(l-1) > 1e-5 {
					t.Fatalf("vertex %d normal length %g", i, l)
				}
			}
			smooth, err := Extract(context.Background(), field, Options{Iso: 0.5})
			if err != nil {
				t.Fatal(err)
			}
			requireClosedManifold(t, smooth)
			// Marching Cubes cuts the voxel corners: slightly less volume.
			if _, v := massProperties(smooth); v >= float64(count) || v < 0.95*float64(count) {
				t.Fatalf("marching cubes volume %g, %d voxels", v, count)
			}
		})
	}
}
